const TITLES = {login:'经销商登录',register:'企业入驻',agreement:'入驻协议',home:'商城首页',products:'全部商品',product:'商品详情',bulk:'Excel批量订货',cart:'购物车',checkout:'确认订货信息',orders:'我的订单',order:'订单详情',pay:'订单付款',aftersales:'售后服务',profile:'企业资料',accounts:'企业子账号',addresses:'收货地址',invoices:'开票信息与发票',commissions:'我的佣金',reconciliation:'我的对账单',password:'修改密码',me:'个人中心'};
const STATUS = {pendingReview:'待审核',rejected:'已驳回',awaitingPayment:'待支付',paid:'待发货',shipped:'待收货',completed:'已完成',returning:'退货中',refunded:'已退款',cancelled:'已取消',pending:'待审核',approved:'已通过',requested:'待退回收货',received:'已退回待退款',refundFailed:'退款待处理',issued:'已开票',failed:'处理失败',unsettled:'未结算',settled:'已结算',success:'成功'};
const PROFILE = [['企业名称','name'],['统一社会信用代码','taxId'],['联系人','contact'],['联系电话','tel'],['省份','province'],['城市','city'],['区县','district'],['详细地址','address']];
const INVOICE = [['发票抬头','title'],['纳税人识别号','taxId'],['注册地址','address'],['注册电话','phone'],['开户银行','bank'],['银行账号','bankAccount'],['接收邮箱','email']];
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const list = value => Array.isArray(value) ? value : [];
const text = value => value === null || value === undefined || value === '' ? '—' : value;
const priceSource = value => ({special:'客户专属价',grade:'经销商等级价',tier:'等级价及数量阶梯',gradeTier:'等级价及数量阶梯'}[value] || value || '经销价');
const token = () => globalThis.crypto?.randomUUID?.() || `order-${Date.now()}-${Math.random().toString(36).slice(2)}`;
const draftKey = ctx => `supor.checkout.${ctx.port}.${ctx.user?.id || ctx.session?.userId || 'guest'}`;
function readDraft(ctx) { try { const value=JSON.parse(globalThis.sessionStorage?.getItem(draftKey(ctx)) || 'null'); return value && Array.isArray(value.items) ? value : null; } catch { return null; } }
function writeDraft(ctx, draft) { if (!globalThis.sessionStorage) throw Error('浏览器未启用会话存储，请启用后继续订货'); globalThis.sessionStorage.setItem(draftKey(ctx),JSON.stringify(draft)); }
function newDraft(ctx,items,source,extra={}) { writeDraft(ctx,{items:items.map(i=>({productId:i.productId,qty:Number(i.qty)})),source,token:token(),...extra});ctx.navigate('checkout'); }
function values(form) { return Object.fromEntries(new FormData(form)); }
function fields(definitions,record={},required=true) { return definitions.map(([label,name])=>field(label,name,record[name] ?? '',{required,type:name==='email'?'email':name==='phone'||name==='tel'?'tel':'text'})).join(''); }
function field(label,name,value='',options={}) { const {type='text',required=false,readonly=false,help='',options:choices=[],min,max,step,placeholder='',autocomplete=''}=options;const newPassword=type==='password'&&autocomplete!=='current-password'&&name!=='oldPassword';const attrs=`name="${esc(name)}" ${required?'required':''} ${readonly?'readonly':''} ${min!==undefined?`min="${esc(min)}"`:''} ${max!==undefined?`max="${esc(max)}"`:''} ${step!==undefined?`step="${esc(step)}"`:''} ${placeholder?`placeholder="${esc(placeholder)}"`:''} ${autocomplete?`autocomplete="${esc(autocomplete)}"`:''} ${newPassword?'minlength="8" pattern="(?=.*[A-Za-z])(?=.*[0-9]).{8,}" title="至少8位，包含字母和数字"':''}`;const hint=newPassword?'至少8位，包含字母和数字':help;return `<label class="shop-field"><span>${esc(label)}${required?'<em aria-hidden="true"> *</em>':''}</span>${type==='select'?`<select ${attrs}>${choices.map(o=>`<option value="${esc(o.value)}" ${String(o.value)===String(value)?'selected':''}>${esc(o.label)}</option>`).join('')}</select>`:type==='textarea'?`<textarea ${attrs} rows="3">${esc(value)}</textarea>`:`<input type="${esc(type)}" ${attrs} ${type==='file'?'':`value="${esc(value)}"`}>`}${hint?`<small>${esc(hint)}</small>`:''}</label>`; }
const button = (label,command,attrs='',kind='') => `<button type="button" class="shop-btn ${kind}" ${command?`data-command="${esc(command)}"`:''} ${attrs}>${esc(label)}</button>`;
const nav = (label,route,params={},kind='link') => `<button type="button" class="shop-btn ${kind}" data-shop-nav="${esc(route)}" data-shop-params="${esc(JSON.stringify(params))}">${esc(label)}</button>`;
const badge = status => `<span class="shop-badge shop-state-${esc(status)}">${esc(STATUS[status]||status||'—')}</span>`;
const empty = (message,action='') => `<div class="shop-empty"><h3>${esc(message)}</h3>${action}</div>`;
const errorSlot = () => '<p class="shop-error" role="alert" data-shop-error hidden></p>';
const check = (label,name,checked=false,attrs='')=>`<label class="shop-check"><input type="checkbox" name="${esc(name)}" ${checked?'checked':''} ${attrs}>${esc(label)}</label>`;
const addressText = a => [a?.province,a?.city,a?.district,a?.detail||a?.address].filter(Boolean).join(' ');
const image = (p,className='') => `<img class="${className}" src="${esc(p?.images?.[0]||p?.image||'assets/sf40hc42.png')}" alt="${esc(p?.name||'商品图片')}" loading="lazy">`;
function ownDealer(ctx) {return list(ctx.state.dealers).find(d=>d.id===ctx.user?.dealerId);}
function ownAddresses(ctx) {return list(ctx.state.addresses).filter(a=>a.dealerId===ctx.user?.dealerId);}
function authorized(ctx,args={}) {return list(ctx.query('products',args));}
function quoted(ctx,id,qty=1) { try { const q=ctx.query('quote',{productId:id,qty:Number(qty)});const unitPrice=Number(q?.unitPrice ?? q?.price);if(!Number.isFinite(unitPrice)||unitPrice<=0)throw Error('暂未配置有效经销价，请联系业务人员');return {...q,unitPrice,total:Number(q.total ?? q.lineTotal ?? unitPrice*Number(qty))}; } catch(error) {return {error:error.message};} }
function itemProblem(p,q,qty) { if(!p)return '商品已下架或不在当前授权范围，请移除后重选';if(!Number.isInteger(Number(qty))||Number(qty)<1)return '订货数量须为正整数';if(q.error)return q.error;if(p.stockStatus==='failed'||p.stockStatus==='unknown')return '库存同步异常，请待库存恢复后下单';if(Number(qty)>Number(p.stock))return `可用库存仅 ${p.stock} ${p.unit||'台'}，请减少数量`;return ''; }
function raise(root,error) { const slot=root.querySelector('[data-shop-error]');if(slot){slot.hidden=false;slot.textContent=error.message||String(error);slot.scrollIntoView?.({block:'nearest'});} }
function bindEvent(root,selector,type,callback) {root.querySelectorAll(selector).forEach(el=>el.addEventListener(type,async event=>{if(type==='submit')event.preventDefault();try{await callback(el,event);}catch(error){raise(root,error);}}));}
function page(ctx,title,html,commands={},mount=()=>{}) {return {title,html:`<div class="shop shop-${esc(ctx.port)}" data-shop-route="${esc(ctx.route)}">${ctx.route!=='home'?`<div class="shop-heading"><h1>${esc(title)}</h1>${!['login','register','agreement','me'].includes(ctx.route)?nav('返回个人中心','me'):''}</div>`:''}${errorSlot()}${html}</div>`,bind(root){bindEvent(root,'[data-shop-nav]','click',el=>ctx.navigate(el.dataset.shopNav,JSON.parse(el.dataset.shopParams||'{}')));bindEvent(root,'[data-command]','click',async el=>{const fn=commands[el.dataset.command];if(!fn)return;el.disabled=true;try{await fn(el,root);}finally{el.disabled=false;}});mount(root);}};}
function scopedModal(ctx,title,html,submit,options={}) {return ctx.modal(title,`<div class="shop shop-${esc(ctx.port)}"><div class="shop-form-grid">${html}</div></div>`,submit,{saveLabel:'保存',...options});}
function categories(ctx,products=authorized(ctx)) { const ids=new Set(products.map(p=>p.categoryId));const all=list(ctx.state.categories);let changed=true;while(changed){changed=false;for(const c of all)if(ids.has(c.id)&&c.parentId&&!ids.has(c.parentId)){ids.add(c.parentId);changed=true;}}return all.filter(c=>c.enabled!==false&&ids.has(c.id)).sort((a,b)=>(a.sort||0)-(b.sort||0)); }
function categoryLabel(ctx,c) {const all=list(ctx.state.categories),parts=[c.name];let p=c.parentId,seen=new Set([c.id]);while(p&&!seen.has(p)){seen.add(p);const parent=all.find(a=>a.id===p);if(!parent)break;parts.unshift(parent.name);p=parent.parentId;}return parts.join(' / ');}
function catalogFilters(ctx) {return `<form data-catalog-filter class="shop-filters">${field('搜索商品','q',ctx.params.get('q')||'',{placeholder:'商品名称 / SKU / 型号'})}${field('商品分类','categoryId',ctx.params.get('categoryId')||'',{type:'select',options:[{value:'',label:'全部授权分类'},...categories(ctx).map(c=>({value:c.id,label:categoryLabel(ctx,c)}))]})}<button class="shop-btn primary" type="submit">查询</button>${nav('重置',ctx.route)}${button('下载含图订货表','download-products')}${ctx.route!=='bulk'?nav('上传订货表','bulk',{q:ctx.params.get('q')||'',categoryId:ctx.params.get('categoryId')||''}):''}</form>`;}
async function downloadProducts(ctx,products) { if(!products.length)throw Error('当前筛选没有可下载商品，请调整筛选条件');const rows=products.map(p=>{const q=quoted(ctx,p.id);return {主图:p.images?.[0]||'',SKU:p.sku,商品名称:p.name,商品型号:p.model,规格:p.spec,单位:p.unit,经销单价:q.error?'暂无有效报价':q.unitPrice,可用库存:p.stock,订货数量:''};});await ctx.downloadExcel('苏泊尔授权商品订货表.xlsx',rows,{images:true,columns:['主图','SKU','商品名称','商品型号','规格','单位','经销单价','可用库存','订货数量']}); }
function productCard(ctx,p) {const q=quoted(ctx,p.id);return `<article class="shop-product"><button type="button" class="shop-product-image" data-shop-nav="product" data-shop-params="${esc(JSON.stringify({id:p.id}))}" aria-label="查看${esc(p.name)}">${image(p)}</button><div class="shop-product-copy"><h3>${nav(p.name,'product',{id:p.id})}</h3><p>${esc(p.model||p.sku)} · ${esc(p.spec)}</p><div class="shop-product-price"><strong>${q.error?'暂无报价':ctx.money(q.unitPrice)}</strong>${button('加入购物车','card-cart',`data-product-id="${esc(p.id)}" ${q.error?'disabled':''}`,'link')}</div><small>${esc(p.stockStatus==='failed'?'库存更新异常':`库存 ${p.stock} ${p.unit||'台'}`)}</small></div></article>`;}
function bindCatalog(ctx,root) {bindEvent(root,'[data-catalog-filter]','submit',form=>ctx.navigate(ctx.route,values(form)));}
function catalogCommands(ctx,products) {return {'download-products':()=>downloadProducts(ctx,products),'card-cart':async el=>{await ctx.run('cartAdd',{productId:el.dataset.productId,qty:1});ctx.refresh();}};}

function loginPage(ctx) {const demos=list(ctx.state.users).filter(u=>u.kind==='dealer'&&u.enabled!==false);return page(ctx,TITLES.login,`<section class="shop-login"><div class="shop-login-brand"><img src="assets/logo.png" alt="苏泊尔"><h2>苏泊尔经销商订货平台</h2><p>精选好产品，让生意更从容。</p><img class="shop-login-product" src="assets/sf40hc42.png" alt="本釜IH电饭煲"></div><div class="shop-login-form"><h2>欢迎登录</h2><p>使用已入驻企业的手机账号登录</p><form data-login-form>${field('账号手机号','phone','',{required:true,type:'tel',autocomplete:'username'})}${field('登录密码','password','',{required:true,type:'password',autocomplete:'current-password'})}<button class="shop-btn primary" type="submit">登录</button></form><p>还未入驻？${nav('企业入驻申请','register')}</p><details class="shop-demo"><summary>填入演示账号</summary>${demos.map(u=>`<button class="shop-btn" type="button" data-demo-phone="${esc(u.phone)}">${esc(u.name)} · ${u.isMain?'主账号':'采购账号'}</button>`).join('')}<small>演示密码：Supor123</small></details></div></section>`,{},root=>{bindEvent(root,'[data-demo-phone]','click',el=>{root.querySelector('[name="phone"]').value=el.dataset.demoPhone;root.querySelector('[name="password"]').value='Supor123';});bindEvent(root,'[data-login-form]','submit',async form=>{const data=values(form);const result=await ctx.run('login',{kind:'dealer',phone:data.phone,password:data.password});if(result?.dealer?.status&&result.dealer.status!=='approved')ctx.navigate('register',{id:result.dealer.id,tab:'status'});else ctx.navigate('home');});});}
function agreementPage(ctx) {const a=ctx.state.config?.agreement||{};return page(ctx,TITLES.agreement,`<article class="shop-section shop-agreement"><h2>${esc(a.title||'经销商入驻协议')}</h2><p class="shop-muted">生效版本 ${esc(a.version||1)} · ${esc(ctx.date(a.updatedAt))}</p><div class="shop-prose">${esc(a.content||'').replace(/\n/g,'<br>')}</div>${nav('返回入驻申请','register')}</article>`);}
function registrationPage(ctx) {
  const dealer=ownDealer(ctx),agreement=ctx.state.config?.agreement||{},reapply=dealer?.status==='rejected';
  if(dealer?.status==='pending')return page(ctx,'入驻审核中',`<section class="shop-section"><h2>资料已提交，等待审核</h2><p>${esc(dealer.name)}</p><p>审核通过后即可选购授权商品。您可以稍后重新登录查看审核结果。</p>${badge('pending')}${nav('返回登录','login')}</section>`);
  return page(ctx,reapply?'修改入驻资料':TITLES.register,`${reapply?`<div class="shop-notice danger"><h3>上次申请已驳回</h3><p>${esc(dealer.reason||'请补充企业资料后重新提交')}</p></div>`:''}<form data-register-form class="shop-section"><h2>账号信息</h2><div class="shop-form-grid">${field('账号手机号','phone',dealer?.phone||'',{required:true,type:'tel',autocomplete:'username'})}${field(reapply?'当前账号密码':'登录密码','password','',{required:true,type:'password',autocomplete:reapply?'current-password':'new-password',help:reapply?'输入原登录密码以确认重提身份':''})}${field('确认密码','confirmation','',{required:true,type:'password',autocomplete:reapply?'current-password':'new-password'})}</div><h2>企业资料</h2><div class="shop-form-grid">${fields(PROFILE,dealer||{})}</div><label class="shop-field"><span>营业执照 *</span><input name="licenseFile" type="file" accept="image/png,image/jpeg,image/webp" ${dealer?.license?'':'required'}><small>上传清晰的营业执照图片，支持 PNG、JPEG、WebP。</small></label><div data-license-preview>${dealer?.license?`<img class="shop-license" src="${esc(dealer.license)}" alt="当前营业执照">`:''}</div><section class="shop-agreement-inline"><h3>${esc(agreement.title)} <small>版本 ${esc(agreement.version)}</small></h3><div class="shop-prose">${esc(agreement.content).replace(/\n/g,'<br>')}</div></section><label class="shop-check"><input type="checkbox" name="agreed" required>我已阅读并同意上述入驻协议</label><div class="shop-actions"><button type="submit" class="shop-btn primary">${reapply?'修改后重新提交审核':'提交入驻申请'}</button>${nav('返回登录','login')}</div></form>`,{},root=>{
    let license=dealer?.license||'',upload=null;
    bindEvent(root,'[name="licenseFile"]','change',async input=>{
      const file=input.files?.[0];if(!file)return;
      license='';upload=ctx.readImage(file);
      try{license=await upload;if(typeof license!=='string'||!license)throw Error('营业执照读取失败，请重新上传');root.querySelector('[data-license-preview]').innerHTML=`<img class="shop-license" src="${esc(license)}" alt="已上传营业执照">`;}finally{upload=null;}
    });
    bindEvent(root,'[data-register-form]','submit',async form=>{
      if(upload)await upload;
      const data=values(form);
      if(data.password!==data.confirmation)throw Error('两次密码不一致，请重新输入');
      if(!form.querySelector('[name="agreed"]').checked)throw Error('请阅读并同意入驻协议');
      if(!license)throw Error('请先上传营业执照图片');
      const result=await ctx.run('register',{...Object.fromEntries(PROFILE.map(([,name])=>[name,data[name]])),phone:data.phone,password:data.password,license,agreed:true,...(reapply?{id:dealer.id}:{})});
      form.innerHTML=`<h2>入驻资料已提交，等待审核</h2><p>${esc(result?.dealer?.name||data.name)}</p><p>审核通过后即可订货。使用您的手机账号登录，可查看审核进度与驳回原因。</p><div class="shop-actions">${badge('pending')}<button type="button" class="shop-btn primary" data-registration-login>前往登录</button></div>`;
      form.querySelector('[data-registration-login]').addEventListener('click',()=>ctx.navigate('login'));
    });
  });
}

function homePage(ctx) {
  const dealer=ownDealer(ctx),grade=list(ctx.state.grades).find(g=>g.id===dealer?.gradeId),products=authorized(ctx);
  const published=ctx.state.decoration?.[ctx.port]?.published,layout=published||{},banner=products.find(product=>product.id===layout.bannerProductId);
  const blocks=list(layout.blocks).filter(block=>block.visible!==false),firstProductBlock=blocks.find(block=>block.type==='products');
  const defaultTitle=!layout.title||layout.title==='好产品，让生意更从容。';
  const headline=defaultTitle?'<span>好产品，</span><span>让生意更从容。</span>':esc(layout.title);
  const hero=layout.title||layout.bannerImage?'<section class="shop-hero"><div><h1>'+headline+'</h1><p>'+esc(layout.subtitle||'')+'</p>'+(banner?nav('查看'+banner.name,'product',{id:banner.id},ctx.port==='pc'?'dark':'primary'):nav('浏览授权商品','products',{},ctx.port==='pc'?'dark':'primary'))+'</div>'+(layout.bannerImage?'<img src="'+esc(layout.bannerImage)+'" alt="'+esc(banner?.name||layout.title)+'">':'')+'</section>':'';
  const categoryChips='<div class="shop-category-chips">'+categories(ctx,products).map(category=>nav(category.name,'products',{categoryId:category.id},'chip')).join('')+'</div>';
  const categoryStrip='<div class="shop-home-category-strip">'+categoryChips+'<p class="shop-muted">已按您的经营范围展示可订商品</p></div>';
  const productFloor=(title,linked,withCategories)=>'<section class="shop-floor"><div class="shop-section-head"><h2>'+esc(title||'精选商品')+'</h2>'+nav('查看全部','products')+'</div>'+(withCategories?categoryStrip:'')+'<div class="shop-products">'+linked.map(product=>productCard(ctx,product)).join('')+'</div>'+(!linked.length?empty('该楼层暂无可订商品'):'')+'</section>';
  const renderBlock=block=>{
    if(block.type==='products')return productFloor(block.title,products.filter(product=>list(block.productIds).includes(product.id)),ctx.port==='pc'&&block===firstProductBlock);
    if(block.type==='category')return '<section class="shop-floor"><h2>'+esc(block.title||'商品分类')+'</h2>'+categoryChips+'</section>';
    if(block.type==='banner')return '<section class="shop-content-banner"><h2>'+esc(block.title)+'</h2><p>'+esc(block.content)+'</p>'+(block.image?'<img src="'+esc(block.image)+'" alt="'+esc(block.title)+'">':'')+list(block.productIds).filter(id=>products.some(product=>product.id===id)).map(id=>nav('查看商品','product',{id},'primary')).join('')+'</section>';
    return '<section class="shop-text-block"><h2>'+esc(block.title)+'</h2><p>'+esc(block.content).replace(/\n/g,'<br>')+'</p>'+(block.image?'<img src="'+esc(block.image)+'" alt="'+esc(block.title)+'">':'')+'</section>';
  };
  let top;
  if(ctx.port==='pc'){
    const orders=ownedOrders(ctx);
    const stats=[['pendingReview','待审核'],['awaitingPayment','待支付'],['shipped','待收货']].map(([status,label])=>'<button type="button" class="shop-home-stat" data-shop-nav="orders" data-shop-params="'+esc(JSON.stringify({tab:status}))+'"><strong data-home-count="'+status+'">'+orders.filter(order=>order.status===status).length+'</strong><small>'+label+'</small></button>').join('');
    top='<div class="shop-home-top">'+hero+'<section class="shop-home-account"><div class="shop-home-identity"><span class="shop-home-avatar" aria-hidden="true">'+esc(dealer?.name?.slice(0,1)||'企')+'</span><div><strong>您好，'+esc(ctx.user?.name||dealer?.contact)+'</strong><p>'+esc(dealer?.name)+'</p></div></div><div><span class="shop-badge">'+esc(grade?.name||'经销商')+'</span></div><div class="shop-home-counts">'+stats+'</div>'+nav('查看我的订单','orders')+'</section></div>'+
      '<div class="shop-home-excel"><div class="shop-home-excel-copy">'+ctx.icon('doc')+'<div><strong>多款商品，一次订货</strong><p>下载带图产品表，填写数量后上传并确认订单</p></div></div><div class="shop-home-excel-actions">'+button('下载产品表','download-products')+nav('上传订货表','bulk',{},'primary')+'</div></div>';
  }else{
    top='<div class="shop-welcome"><div><span>您好，'+esc(ctx.user?.name||dealer?.contact)+'</span><strong>'+esc(dealer?.name)+'</strong></div><span class="shop-badge">'+esc(grade?.name||'经销商')+'</span></div>'+
      '<form class="shop-home-search" data-home-search><label class="shop-sr-only" for="shop-home-q">搜索商品名称或型号</label><input id="shop-home-q" name="q" placeholder="搜索商品名称 / 型号 / SKU"><button type="submit" class="shop-btn primary">搜索</button></form>'+hero+
      '<div class="shop-shortcuts">'+[['Excel订货','bulk',{}],['待审核订单','orders',{tab:'pendingReview'}],['待支付订单','orders',{tab:'awaitingPayment'}],['待收货订单','orders',{tab:'shipped'}]].map(([label,route,params])=>nav(label,route,params)).join('')+'</div>';
  }
  const intro=ctx.port==='mini'||(!firstProductBlock&&published!=null)?'<section class="shop-catalog-intro"><h2>按分类选购</h2>'+categoryStrip+'</section>':'';
  const fallback=published==null?productFloor('厨房小家电',products.slice(0,4),ctx.port==='pc'):'';
  const footer=ctx.port==='mini'?'<footer class="shop-footer">'+esc(layout.footer||'苏泊尔经销商订货平台')+'</footer>':'';
  return page(ctx,TITLES.home,top+intro+blocks.map(renderBlock).join('')+fallback+footer,catalogCommands(ctx,products),root=>bindEvent(root,'[data-home-search]','submit',form=>ctx.navigate('products',values(form))));
}
function productsPage(ctx) {const args={q:ctx.params.get('q')||'',categoryId:ctx.params.get('categoryId')||''},products=authorized(ctx,args),size=4,pages=Math.max(1,Math.ceil(products.length/size)),current=Math.max(1,Math.min(pages,Number(ctx.params.get('page'))||1));return page(ctx,TITLES.products,`${catalogFilters(ctx)}<div class="shop-section-head"><p class="shop-muted">共 ${products.length} 款授权商品，按当前企业适用价格展示</p></div><div class="shop-products">${products.slice((current-1)*size,current*size).map(p=>productCard(ctx,p)).join('')}</div>${!products.length?empty('未找到可订商品，请调整搜索或分类条件',nav('清除筛选','products')):''}<nav class="shop-pagination" aria-label="商品分页">${nav('上一页','products',{...args,page:Math.max(1,current-1)})}<span>第 ${current} / ${pages} 页</span>${nav('下一页','products',{...args,page:Math.min(pages,current+1)})}</nav>`,catalogCommands(ctx,products),root=>bindCatalog(ctx,root));}
function tierQuoteRows(ctx,tier,p) {
  const mins=[...new Set([...list(tier.steps).map(step=>Number(step.min)),...Object.keys(tier.skuOverrides?.[p.id]||{}).map(Number)])].filter(n=>n>0).sort((a,b)=>a-b);
  return mins.map(min=>{const quote=quoted(ctx,p.id,min);return '<li>单规格满 '+min+' '+esc(p.unit||'台')+'：'+(quote.error?esc(quote.error):ctx.money(quote.unitPrice)+' · '+esc(priceSource(quote.priceSource||quote.source)))+'</li>';}).join('');
}
function productPage(ctx) {const products=authorized(ctx),p=products.find(p=>p.id===ctx.params.get('id'));if(!p)return page(ctx,TITLES.product,empty('商品不可订购：已下架或不在授权范围',nav('返回商品列表','products')));const q=quoted(ctx,p.id),tier=list(ctx.state.tiers).find(t=>t.enabled!==false&&(t.id===p.tierId||list(t.productIds).includes(p.id)));let qty=1;const group=products.filter(a=>a.id===p.id||(a.code&&a.code===p.code));return page(ctx,p.name,`<div class="shop-detail"><section class="shop-gallery"><div class="shop-gallery-main">${image(p,'shop-main-image')}</div><div class="shop-thumbs">${list(p.images).map((url,i)=>`<button type="button" class="${i===0?'selected':''}" data-image-url="${esc(url)}" aria-label="商品图片${i+1}"><img src="${esc(url)}" alt="${esc(p.name)} 图片${i+1}"></button>`).join('')}</div></section><section class="shop-detail-info"><h2>${esc(p.name)}</h2><p class="shop-muted">商品型号 ${esc(p.model||p.sku)}</p><div class="shop-pricebox"><span>您的经销价</span><strong data-unit-price>${q.error?'暂无报价':ctx.money(q.unitPrice)}</strong><small data-price-source>${esc(q.error||priceSource(q.priceSource||q.source))}</small></div>${field('包装规格','productId',p.id,{type:'select',options:group.map(g=>({value:g.id,label:`${g.spec} · ${g.sku}`}))})}<div class="shop-detail-row"><label for="shop-detail-qty">订货数量</label><div class="shop-quantity">${button('−','qty-minus','aria-label="减少数量"')}<input id="shop-detail-qty" aria-label="订货数量" name="qty" type="number" min="1" step="1" value="1">${button('+','qty-plus','aria-label="增加数量"')}</div><span>${esc(p.unit||'台')}</span></div><p class="shop-muted" data-stock>可用库存 ${p.stock} ${esc(p.unit||'台')} · 更新于 ${esc(ctx.date(p.stockTime))}${p.stockStatus==='failed'?' · 库存同步异常':''}</p><div class="shop-detail-row"><span>订货金额</span><strong class="shop-total" data-detail-total>${q.error?'—':ctx.money(q.total)}</strong></div><p class="shop-error" data-quote-error ${q.error?'':'hidden'}>${esc(q.error||'')}</p><div class="shop-actions">${button('加入购物车','add-cart','','outline')}${button('立即下单','buy-now','','primary')}${nav('查看购物车','cart')}</div><p class="shop-notice">提交订单 → 审核通过 → 在线付款 → 发货收货</p>${tier?`<details class="shop-tier"><summary>查看数量阶梯优惠</summary><ul>${tierQuoteRows(ctx,tier,p)}</ul><p>客户专属价优先，专属价不再叠加阶梯折扣。</p></details>`:''}</section></div><section class="shop-section"><h2>商品信息与规格参数</h2><dl class="shop-definition"><dt>商品名称</dt><dd>${esc(p.name)}</dd><dt>SKU</dt><dd>${esc(p.sku)}</dd><dt>商品规格</dt><dd>${esc(p.spec)}</dd><dt>订货单位</dt><dd>${esc(p.unit)}</dd><dt>单位体积</dt><dd>${esc(p.volume)} m³</dd>${Object.entries(p.attrs||{}).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl></section>`,{
    'qty-minus':(_,root)=>{const input=root.querySelector('[name="qty"]');input.value=Math.max(1,Number(input.value)-1);input.dispatchEvent(new Event('input',{bubbles:true}));},'qty-plus':(_,root)=>{const input=root.querySelector('[name="qty"]');input.value=Number(input.value)+1;input.dispatchEvent(new Event('input',{bubbles:true}));},
    'add-cart':async(_,root)=>{const id=root.querySelector('[name="productId"]').value;qty=Number(root.querySelector('[name="qty"]').value);const selected=products.find(p=>p.id===id),q=quoted(ctx,id,qty),problem=itemProblem(selected,q,qty);if(problem)throw Error(problem);await ctx.run('cartAdd',{productId:id,qty});ctx.refresh();},
    'buy-now':(_,root)=>{const id=root.querySelector('[name="productId"]').value;qty=Number(root.querySelector('[name="qty"]').value);const problem=itemProblem(products.find(p=>p.id===id),quoted(ctx,id,qty),qty);if(problem)throw Error(problem);newDraft(ctx,[{productId:id,qty}],'buyNow');}
  },root=>{const update=()=>{const id=root.querySelector('[name="productId"]').value,selected=products.find(p=>p.id===id);qty=Number(root.querySelector('[name="qty"]').value);const q=quoted(ctx,id,qty),problem=itemProblem(selected,q,qty);root.querySelector('[data-unit-price]').textContent=q.error?'暂无报价':ctx.money(q.unitPrice);root.querySelector('[data-detail-total]').textContent=q.error?'—':ctx.money(q.total);root.querySelector('[data-price-source]').textContent=priceSource(q.priceSource||q.source);const slot=root.querySelector('[data-quote-error]');slot.hidden=!problem;slot.textContent=problem;root.querySelector('[data-stock]').textContent=`可用库存 ${selected.stock} ${selected.unit||'台'} · 更新于 ${ctx.date(selected.stockTime)}`;};bindEvent(root,'[name="qty"]','input',update);bindEvent(root,'[name="productId"]','change',update);bindEvent(root,'[data-image-url]','click',el=>{root.querySelector('.shop-main-image').src=el.dataset.imageUrl;root.querySelectorAll('[data-image-url]').forEach(b=>b.classList.toggle('selected',b===el));});});}

function bulkPage(ctx) {
  const products=authorized(ctx,{q:ctx.params.get('q')||'',categoryId:ctx.params.get('categoryId')||''});let rows=[],validated=null;
  return page(ctx,TITLES.bulk,`${catalogFilters(ctx)}<section class="shop-section"><h2>上传填写后的订货表</h2><p class="shop-muted">下载表含当前筛选全部授权商品和图片，每种 SKU 规格一行。在“订货数量”列填写正整数，未填写的商品不订购。</p><label class="shop-field"><span>Excel订货文件</span><input type="file" name="orderFile" accept=".xlsx"><small>仅支持真实 .xlsx 工作簿；重复SKU、越权、下架、超库存和无价记录会阻止导入。</small></label><div data-import-result aria-live="polite">${empty('尚未上传订货表')}</div><div class="shop-actions">${button('重新校验','import-validate','disabled')}${button('确认导入并核对订单','import-confirm','disabled','primary')}</div></section>`,{
    ...catalogCommands(ctx,products),
    'import-validate':async(_,root)=>{validated=null;root.querySelector('[data-command="import-confirm"]').disabled=true;const result=await ctx.run('importRows',{type:'order',rows});validated=list(result?.items);if(!validated.length)throw Error('没有有效订货数量，请填写后重新上传');showImport(root);},
    'import-confirm':()=>{if(!validated?.length)throw Error('请先上传并通过完整校验');newDraft(ctx,validated,'excel');}
  },root=>{
    bindCatalog(ctx,root);
    bindEvent(root,'[name="orderFile"]','change',async input=>{validated=null;rows=[];root.querySelector('[data-command="import-confirm"]').disabled=true;const file=input.files?.[0];if(!file)return;const result=root.querySelector('[data-import-result]');result.innerHTML='<p role="status">正在读取并校验订货表…</p>';try{const parsed=await ctx.readExcel(file);rows=Array.isArray(parsed)?parsed:list(parsed?.rows);if(!rows.length)throw Error('工作簿没有数据，请使用下载的订货表填写数量');root.querySelector('[data-command="import-validate"]').disabled=false;const output=await ctx.run('importRows',{type:'order',rows});validated=list(output?.items);if(!validated.length)throw Error('没有有效订货数量，请填写后重新上传');showImport(root);}catch(error){result.innerHTML=`<div class="shop-notice danger"><h3>订货表未通过校验</h3><p>${esc(error.message).replace(/\n/g,'<br>')}</p><p>请修正以下行中的 SKU 或数量，再上传原工作簿。</p></div>${rawRows()}`;throw error;}});
  });
  function rawRows(){return rows.length?`<div class="shop-table-wrap"><table class="shop-table"><thead><tr><th>工作表行</th><th>SKU</th><th>订货数量</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${i+2}</td><td>${esc(r.SKU||r.sku)}</td><td>${esc(r.订货数量??r.数量??r.qty)}</td></tr>`).join('')}</tbody></table></div>`:'';}
  function showImport(root){root.querySelector('[data-import-result]').innerHTML=`<div class="shop-notice"><h3>校验通过，共 ${validated.length} 种规格</h3><p>导入只生成本次订货明细，不会修改购物车。</p></div><div class="shop-import-items">${validated.map(i=>{const p=authorized(ctx).find(p=>p.id===i.productId),q=quoted(ctx,i.productId,i.qty);return `<div class="shop-line-item">${image(p)}<div><strong>${esc(p?.name)}</strong><small>${esc(p?.sku)} · ${esc(p?.spec)}</small><p>${i.qty} ${esc(p?.unit||'台')} · ${q.error?esc(q.error):ctx.money(q.total)}</p></div></div>`;}).join('')}</div>`;root.querySelector('[data-command="import-confirm"]').disabled=false;}
}
function cartPage(ctx) {
  const cart=list(ctx.state.carts?.[ctx.user?.id]),products=authorized(ctx);const selected=cart.filter(i=>i.selected);let total=0;
  const rows=cart.map(i=>{const p=products.find(p=>p.id===i.productId),q=quoted(ctx,i.productId,i.qty),problem=itemProblem(p,q,i.qty);if(i.selected&&!problem)total+=q.total;return `<article class="shop-cart-item"><label class="shop-check"><input type="checkbox" data-cart-select="${esc(i.productId)}" ${i.selected?'checked':''} aria-label="选择${esc(p?.name||'失效商品')}"></label>${p?image(p):'<div class="shop-unavailable-image">商品失效</div>'}<div class="shop-cart-copy"><strong>${p?nav(p.name,'product',{id:p.id}):'商品已失效'}</strong><small>${esc(p?.sku||'')} · ${esc(p?.spec||'')}</small><span class="shop-muted">库存 ${esc(p?.stock??'未知')} ${esc(p?.unit||'台')}</span>${problem?`<p class="shop-error">${esc(problem)}</p>`:''}</div><div class="shop-cart-price"><small>经销单价</small><strong>${q.error?'—':ctx.money(q.unitPrice)}</strong></div><label class="shop-field shop-cart-quantity"><span>订货数量</span><input type="number" min="1" step="1" value="${i.qty}" data-cart-qty="${esc(i.productId)}" aria-label="${esc(p?.name||'失效商品')}订货数量"></label><div class="shop-cart-price"><small>金额小计</small><strong>${q.error?'—':ctx.money(q.total)}</strong></div>${button('删除','cart-delete',`data-product-id="${esc(i.productId)}"`,'link')}</article>`;}).join('');
  return page(ctx,TITLES.cart,cart.length?`<div class="shop-section-head"><label class="shop-check"><input data-cart-all type="checkbox" ${selected.length===cart.length?'checked':''}>全选商品</label>${button('删除选中商品','cart-delete-selected')}</div><div class="shop-cart-list">${rows}</div><div class="shop-summary-bar"><span>已选 ${selected.length} 种规格 · ${selected.reduce((n,i)=>n+Number(i.qty),0)} 件</span><div><span>合计</span><strong class="shop-total">${ctx.money(total)}</strong>${button('去确认订单','cart-checkout',`${!selected.length?'disabled':''}`,'primary')}</div></div>`:empty('购物车还没有商品',nav('去选购商品','products',{},'primary')),
  {'cart-delete':async el=>{if(await ctx.confirm('删除商品','确定从购物车移除此商品？')){await ctx.run('cartRemove',{ids:[el.dataset.productId]});ctx.refresh();}},'cart-delete-selected':async(_,root)=>{const current=cartInputs(root);if(!current.length)throw Error('请先勾选要删除的商品');if(await ctx.confirm('删除选中商品',`确定移除已勾选的 ${current.length} 种规格？`)){await ctx.run('cartRemove',{ids:current.map(i=>i.productId)});ctx.refresh();}},'cart-checkout':async(_,root)=>{const current=cartInputs(root);if(!current.length)throw Error('请先勾选商品');for(const i of current){const problem=itemProblem(products.find(p=>p.id===i.productId),quoted(ctx,i.productId,i.qty),i.qty);if(problem)throw Error(problem);}for(const i of current)await ctx.run('cartUpdate',{productId:i.productId,qty:i.qty,selected:true});newDraft(ctx,current,'cart');}},root=>{bindEvent(root,'[data-cart-select]','change',async el=>{await ctx.run('cartSelect',{ids:[el.dataset.cartSelect],selected:el.checked});ctx.refresh();});bindEvent(root,'[data-cart-all]','change',async el=>{await ctx.run('cartSelect',{ids:cart.map(i=>i.productId),selected:el.checked});ctx.refresh();});bindEvent(root,'[data-cart-qty]','input',()=>cartPreview(ctx,root,products));bindEvent(root,'[data-cart-qty]','change',async el=>{await ctx.run('cartUpdate',{productId:el.dataset.cartQty,qty:Number(el.value),selected:el.closest('.shop-cart-item').querySelector('[data-cart-select]').checked});cartPreview(ctx,root,products);});});
}
function cartInputs(root){return [...root.querySelectorAll('[data-cart-select]')].filter(input=>input.checked).map(input=>({productId:input.dataset.cartSelect,qty:Number(input.closest('.shop-cart-item').querySelector('[data-cart-qty]').value)}));}
function cartPreview(ctx,root,products){
  let total=0,count=0,kinds=0,invalid=false;
  for(const input of root.querySelectorAll('[data-cart-qty]')){const product=products.find(p=>p.id===input.dataset.cartQty),qty=Number(input.value),quote=quoted(ctx,input.dataset.cartQty,qty),problem=itemProblem(product,quote,qty),row=input.closest('.shop-cart-item'),prices=row.querySelectorAll('.shop-cart-price strong');prices[0].textContent=quote.error?'—':ctx.money(quote.unitPrice);prices[1].textContent=problem?'—':ctx.money(quote.total);if(row.querySelector('[data-cart-select]').checked){kinds++;count+=Number.isInteger(qty)&&qty>0?qty:0;if(problem)invalid=true;else total+=quote.total;}}
  root.querySelector('.shop-summary-bar > span').textContent=`已选 ${kinds} 种规格 · ${count} 件`;root.querySelector('.shop-summary-bar .shop-total').textContent=invalid?'—':ctx.money(total);
}
function addressForm(a={}) {return `${field('收货联系人','contact',a.contact||'',{required:true})}${field('收货手机号','phone',a.phone||'',{type:'tel',required:true})}${field('省份','province',a.province||'',{required:true,placeholder:'例如：浙江省'})}${field('城市','city',a.city||'',{required:true,placeholder:'例如：杭州市'})}${field('区县','district',a.district||'',{required:true})}${field('详细地址','detail',a.detail||'',{required:true,type:'textarea',placeholder:'街道、门牌号及仓库位置'})}${check('设为默认收货地址','isDefault',a.isDefault)}`;}
function saveAddressDialog(ctx,a={},after=()=>ctx.refresh()) {return scopedModal(ctx,a.id?'编辑收货地址':'新增收货地址',addressForm(a),async(data,form)=>{const result=await ctx.run('saveAddress',{...(a.id?{id:a.id}:{}),contact:data.contact,phone:data.phone,province:data.province,city:data.city,district:data.district,detail:data.detail,isDefault:form.querySelector('[name="isDefault"]').checked});after(result?.address||result);},{saveLabel:'保存地址'});}
function addressCard(ctx,a,{selected=false,choose=false}={}) {return `<article class="shop-address ${selected?'selected':''}">${choose?`<label class="shop-address-choice"><input type="radio" name="addressId" value="${esc(a.id)}" ${selected?'checked':''} aria-label="选择${esc(a.contact)}的收货地址"><span>使用此地址</span></label>`:''}<div class="shop-address-name"><strong>${esc(a.contact)}</strong><span>${esc(a.phone)}</span>${a.isDefault?'<span class="shop-badge neutral">默认地址</span>':''}</div><p>${esc(addressText(a))}</p><div class="shop-actions">${button('编辑','address-edit',`data-address-id="${esc(a.id)}"`,'link')}${button('删除','address-delete',`data-address-id="${esc(a.id)}"`,'link')}${!a.isDefault?button('设为默认','address-default',`data-address-id="${esc(a.id)}"`,'link'):''}</div></article>`;}
function addressCommands(ctx,{checkout=false,draft=null}={}) {const addresses=ownAddresses(ctx);const after=a=>{if(checkout&&a?.id){draft.addressId=a.id;writeDraft(ctx,draft);}ctx.refresh();};return {'address-new':()=>saveAddressDialog(ctx,{},after),'address-edit':el=>{const a=addresses.find(a=>a.id===el.dataset.addressId);if(!a)throw Error('地址已不存在，请刷新');return saveAddressDialog(ctx,a,after);},'address-delete':async el=>{const id=el.dataset.addressId;if(await ctx.confirm('删除收货地址','删除后不可再用于新订单，已提交订单的地址不会改变。')){await ctx.run('deleteAddress',{id});if(checkout&&draft.addressId===id){delete draft.addressId;writeDraft(ctx,draft);}ctx.refresh();}},'address-default':async el=>{const a=addresses.find(a=>a.id===el.dataset.addressId);if(!a)throw Error('地址已不存在');await ctx.run('saveAddress',{id:a.id,contact:a.contact,phone:a.phone,province:a.province,city:a.city,district:a.district,detail:a.detail,isDefault:true});ctx.refresh();}};}
function addressesPage(ctx) {const addresses=ownAddresses(ctx),draft=readDraft(ctx),choose=ctx.params.get('tab')==='select';return page(ctx,TITLES.addresses,`<div class="shop-section-head"><p class="shop-muted">维护本企业收货地址，历史订单保留原地址快照。</p>${button('新增收货地址','address-new','','primary')}</div><div class="shop-addresses">${addresses.map(a=>addressCard(ctx,a,{choose,selected:draft?.addressId===a.id})).join('')}</div>${!addresses.length?empty('尚未添加收货地址'):''}${choose?button('使用选择的地址返回订单','address-use','','primary'):''}`,{...addressCommands(ctx), 'address-use':(_,root)=>{const id=root.querySelector('[name="addressId"]:checked')?.value;if(!id)throw Error('请选择收货地址');if(!draft)throw Error('没有待提交订单，请先选购商品');draft.addressId=id;writeDraft(ctx,draft);ctx.navigate('checkout');}});}
async function syncDraftCartLine(ctx,draft,item) {
  if(draft.source!=='cart'||draft.orderId)return;
  const exists=list(ctx.state.carts?.[ctx.user.id]).some(line=>line.productId===item.productId);
  await ctx.run(exists?'cartUpdate':'cartAdd',exists?{productId:item.productId,qty:item.qty,selected:true}:{productId:item.productId,qty:item.qty});
}
function addDraftItems(ctx,draft) {const products=authorized(ctx);let chosen=new Set();return scopedModal(ctx,'添加订货商品',`<label class="shop-field shop-full"><span>查找商品</span><input data-draft-search placeholder="商品名称 / SKU"></label><div class="shop-full shop-modal-products">${products.map(p=>`<label class="shop-modal-product" data-product-search="${esc(`${p.name} ${p.sku}`.toLowerCase())}"><input name="productIds" type="checkbox" value="${esc(p.id)}" ${draft.items.some(i=>i.productId===p.id)?'disabled':''}>${image(p)}<span><strong>${esc(p.name)}</strong><small>${esc(p.sku)} · ${esc(p.spec)}</small></span><input type="number" name="qty-${esc(p.id)}" min="1" step="1" value="1" aria-label="${esc(p.name)}订货数量"></label>`).join('')}</div><p class="shop-full shop-muted" data-draft-chosen>已选择 0 种规格</p>`,async(data,form)=>{const ids=new FormData(form).getAll('productIds');if(!ids.length)throw Error('请先勾选要添加的商品');const additions=ids.map(id=>({productId:id,qty:Number(form.querySelector(`[name="qty-${id}"]`).value)}));for(const i of additions){const problem=itemProblem(products.find(p=>p.id===i.productId),quoted(ctx,i.productId,i.qty),i.qty);if(problem)throw Error(problem);}for(const item of additions)await syncDraftCartLine(ctx,draft,item);draft.items.push(...additions);writeDraft(ctx,draft);ctx.refresh();},{saveLabel:'添加至本次订单',wide:ctx.port==='pc',onMount(dialog){bindEvent(dialog,'[data-draft-search]','input',el=>{dialog.querySelectorAll('[data-product-search]').forEach(row=>row.hidden=!row.dataset.productSearch.includes(el.value.trim().toLowerCase()));});bindEvent(dialog,'[name="productIds"]','change',el=>{if(el.checked)chosen.add(el.value);else chosen.delete(el.value);dialog.querySelector('[data-draft-chosen]').textContent=`已选择 ${chosen.size} 种规格`;});}});}
function checkoutInputs(root,draft) {
  draft.items=[...root.querySelectorAll('[data-draft-qty]')].map(input=>({productId:input.dataset.draftQty,qty:Number(input.value)}));
  draft.remark=root.querySelector('[name="remark"]').value;
  draft.addressId=root.querySelector('[name="addressId"]:checked')?.value;
  return draft;
}
function checkoutPreview(ctx,root,draft,products) {
  let total=0,count=0,volume=0,invalid=false;
  for(const item of draft.items){
    const product=products.find(record=>record.id===item.productId),quote=quoted(ctx,item.productId,item.qty),problem=itemProblem(product,quote,item.qty);
    const row=[...root.querySelectorAll('[data-draft-qty]')].find(input=>input.dataset.draftQty===item.productId)?.closest('.shop-checkout-item');
    if(row){
      row.querySelector('[data-draft-quote]').textContent='经销单价 '+(quote.error?'—':ctx.money(quote.unitPrice))+' · '+priceSource(quote.priceSource||quote.source);
      row.querySelector('[data-draft-line-total]').textContent=quote.error?'—':ctx.money(quote.total);
      const error=row.querySelector('[data-draft-problem]');error.textContent=problem;error.hidden=!problem;
    }
    if(Number.isInteger(item.qty)&&item.qty>0)count+=item.qty;
    if(problem)invalid=true;
    else{total+=quote.total;volume+=Number(product.volume||0)*item.qty;}
  }
  root.querySelectorAll('[data-checkout-total]').forEach(node=>node.textContent=invalid?'—':ctx.money(total));
  root.querySelector('[data-checkout-count]').textContent=count+' 件';
  root.querySelector('[data-checkout-volume]').textContent=invalid?'—':volume.toFixed(3)+' m³';
}
function checkoutPage(ctx) {
  const draft=readDraft(ctx);if(!draft?.items.length)return page(ctx,TITLES.checkout,empty('没有待提交的订货明细',nav('去选购商品','products',{},'primary')));
  const products=authorized(ctx),addresses=ownAddresses(ctx),selectedId=draft.addressId||addresses.find(a=>a.isDefault)?.id||addresses[0]?.id;let total=0,count=0,volume=0;const problems=[];
  const rows=draft.items.map(i=>{const p=products.find(p=>p.id===i.productId),q=quoted(ctx,i.productId,i.qty),problem=itemProblem(p,q,i.qty);if(problem)problems.push(problem);else total+=q.total;count+=Number(i.qty)||0;if(p?.volume!==undefined)volume+=Number(p.volume)*Number(i.qty);return `<article class="shop-checkout-item">${p?image(p):'<div class="shop-unavailable-image">商品失效</div>'}<div class="shop-item-copy"><strong>${esc(p?.name||'商品不可订购')}</strong><small>${esc(p?.sku||'')} · ${esc(p?.spec||'')}</small><p data-draft-quote>经销单价 ${q.error?'—':ctx.money(q.unitPrice)} · ${esc(priceSource(q.priceSource||q.source))}</p><p class="shop-error" data-draft-problem ${problem?'':'hidden'}>${esc(problem)}</p></div><label class="shop-field shop-inline-qty"><span>数量</span><input type="number" min="1" step="1" data-draft-qty="${esc(i.productId)}" value="${i.qty}" aria-label="${esc(p?.name||'商品')}数量"></label><strong data-draft-line-total>${q.error?'—':ctx.money(q.total)}</strong>${button('移除','draft-remove',`data-product-id="${esc(i.productId)}"`,'link')}</article>`;}).join('');
  return page(ctx,draft.orderId?'修正订单并重新提交':TITLES.checkout,`<p class="shop-muted">${draft.orderId?'本次修改会重新进入审核，保留原审核记录。':'选择商品 → 确认订单 → 审核与付款'}</p><section class="shop-section"><div class="shop-section-head"><h2>收货地址</h2>${button('新增收货地址','address-new')}</div><div class="shop-addresses shop-checkout-addresses">${addresses.map(a=>addressCard(ctx,a,{selected:a.id===selectedId,choose:true})).join('')}</div>${!addresses.length?empty('请先新增收货地址，缺少地址无法提交'):''}</section><section class="shop-section"><div class="shop-section-head"><h2>商品明细</h2>${button('添加商品','draft-add')}</div><div>${rows}</div>${field('订单备注','remark',draft.remark||'',{type:'textarea',placeholder:'收货或订货备注（选填）'})}</section><div class="shop-checkout-bottom"><div class="shop-notice"><p>订单提交后进入审核，通过后再付款。</p><p>收货地址、商品和成交价格将作为本次订单快照保存。</p>${problems.length?`<p class="shop-error">存在 ${problems.length} 项待修正内容，请检查商品明细。</p>`:''}</div><section class="shop-order-summary"><dl><dt>商品数量</dt><dd data-checkout-count>${count} 件</dd><dt>总体积</dt><dd data-checkout-volume>${volume.toFixed(3)} m³</dd><dt>商品金额</dt><dd data-checkout-total>${ctx.money(total)}</dd><dt>订货总额</dt><dd class="shop-total" data-checkout-total>${ctx.money(total)}</dd></dl>${button(draft.orderId?'重新提交审核':'提交订单审核','submit-order','','primary')}</section></div>`,{
    ...addressCommands(ctx,{checkout:true,draft}), 'draft-add':()=>addDraftItems(ctx,draft), 'draft-remove':el=>{draft.items=draft.items.filter(i=>i.productId!==el.dataset.productId);writeDraft(ctx,draft);ctx.refresh();},
    'submit-order':async(_,root)=>{checkoutInputs(root,draft);writeDraft(ctx,draft);if(!draft.addressId)throw Error('请选择或新增收货地址');if(!draft.items.length)throw Error('请先添加商品');for(const i of draft.items){const problem=itemProblem(products.find(p=>p.id===i.productId),quoted(ctx,i.productId,i.qty),i.qty);if(problem)throw Error(problem);}for(const item of draft.items)await syncDraftCartLine(ctx,draft,item);const result=draft.orderId?await ctx.run('resubmitOrder',{id:draft.orderId,items:draft.items,addressId:draft.addressId,remark:draft.remark}):await ctx.run('submitOrder',{items:draft.items,addressId:draft.addressId,remark:draft.remark,source:draft.source,idempotencyKey:draft.token,fromCart:draft.source==='cart'});globalThis.sessionStorage.removeItem(draftKey(ctx));ctx.navigate('order',{id:result?.order?.id||result?.id});}
  },root=>{bindEvent(root,'[name="remark"]','input',el=>{draft.remark=el.value;writeDraft(ctx,draft);});bindEvent(root,'[name="addressId"]','change',el=>{if(el.checked){draft.addressId=el.value;writeDraft(ctx,draft);root.querySelectorAll('.shop-address').forEach(card=>card.classList.toggle('selected',card.querySelector('[name="addressId"]').checked));}});bindEvent(root,'[data-draft-qty]','input',el=>{draft.items.find(item=>item.productId===el.dataset.draftQty).qty=Number(el.value);writeDraft(ctx,draft);checkoutPreview(ctx,root,draft,products);});});
}

function ownedOrders(ctx) {return list(ctx.query('orders'));}
function ownedOrder(ctx,id) {try{return ctx.query('order',{id});}catch{return null;}}
function orderButtons(ctx,o,includeDetail=true) {const attrs=`data-order-id="${esc(o.id)}"`;return `<div class="shop-actions">${includeDetail?nav('订单详情','order',{id:o.id}):''}${o.status==='awaitingPayment'?nav('立即付款','pay',{id:o.id},'primary'):''}${['pendingReview','rejected','awaitingPayment'].includes(o.status)?button('取消订单','order-cancel',attrs,'link'):''}${o.status==='rejected'&&o.accountId===ctx.user?.id?button('修正并重提','order-edit',attrs,'primary'):''}${o.status==='shipped'?button('确认收货','order-receive',attrs,'primary'):''}${o.status==='shipped'&&o.size==='small'?button('整单拒收','order-refuse',attrs,'link'):''}${o.status==='completed'?button('申请发票','order-invoice',attrs):''}${['returning','refunded'].includes(o.status)?nav('售后进度','aftersales',{orderId:o.id}):''}</div>`;}
function editOrder(ctx,o) {if(o.accountId!==ctx.user?.id)throw Error('请使用原下单账号修正并重新提交此订单');const addresses=ownAddresses(ctx);const a=addresses.find(a=>a.contact===o.addressSnapshot?.contact&&addressText(a)===addressText(o.addressSnapshot));newDraft(ctx,list(o.items),['buyNow','cart','excel'].includes(o.source)?o.source:'buyNow',{orderId:o.id,remark:o.remark||'',...(a?{addressId:a.id}:{})});}
function invoiceProfile(ctx) {return list(ctx.state.invoiceProfiles).find(p=>p.dealerId===ctx.user?.dealerId);}
function invoiceForm(p={}) {return fields(INVOICE,p);}
function requestInvoiceDialog(ctx,o) {const existing=list(ctx.state.invoices).find(i=>i.orderId===o.id&&i.dealerId===ctx.user?.dealerId);if(existing){ctx.navigate('invoices',{id:existing.id});return;}const p=invoiceProfile(ctx);return scopedModal(ctx,'申请订单发票',`<div class="shop-full shop-notice">订单 ${esc(o.no)} · 开票金额 ${ctx.money(o.total)}<br>申请后由开票系统处理，可在发票列表查看结果。</div>${invoiceForm(p||{title:ownDealer(ctx)?.name,taxId:ownDealer(ctx)?.taxId})}`,async(data)=>{await ctx.run('requestInvoice',{id:o.id,profile:Object.fromEntries(INVOICE.map(([,key])=>[key,data[key]]))});ctx.navigate('invoices');},{saveLabel:'提交开票申请',wide:ctx.port==='pc'});}
function orderCommands(ctx,orders=ownedOrders(ctx)) {const find=el=>{const o=orders.find(o=>o.id===el.dataset.orderId);if(!o)throw Error('订单不在当前账号范围内');return o;};return {
  'order-edit':el=>editOrder(ctx,find(el)),
  'order-cancel':async el=>{const o=find(el);if(await ctx.confirm('取消未付款订单',`确定取消订单 ${esc(o.no)}？取消后该订单不再进行审核或付款。`)){await ctx.run('cancelOrder',{id:o.id});ctx.refresh();}},
  'order-receive':async el=>{const o=find(el);if(await ctx.confirm('确认已收货',`请确认订单 ${esc(o.no)} 的全部商品已收到。`)){await ctx.run('receiveOrder',{id:o.id});ctx.refresh();}},
  'order-refuse':el=>{const o=find(el);return scopedModal(ctx,'小件订单整单拒收',`<div class="shop-full shop-notice">订单 ${esc(o.no)} · 整单金额 ${ctx.money(o.total)}<br>退回商品确认收货后，将按原支付渠道退款。</div>${field('拒收原因','reason','',{required:true,type:'textarea',placeholder:'请说明拒收原因'})}`,async data=>{await ctx.run('refuseOrder',{id:o.id,reason:data.reason});ctx.navigate('aftersales',{orderId:o.id});},{saveLabel:'提交拒收申请'});},
  'order-invoice':el=>requestInvoiceDialog(ctx,find(el))
};}
function orderFilters(ctx) {const accounts=list(ctx.state.users).filter(u=>u.dealerId===ctx.user?.dealerId);return `<form data-order-filter class="shop-filters">${field('订单检索','q',ctx.params.get('q')||'',{placeholder:'订单编号 / 商品名称 / SKU'})}${ctx.user?.isMain?field('下单账号','accountId',ctx.params.get('accountId')||'',{type:'select',options:[{value:'',label:'本企业全部账号'},...accounts.map(u=>({value:u.id,label:`${u.name} ${u.phone}`}))]}):''}${field('开始日期','from',ctx.params.get('from')||'',{type:'date'})}${field('结束日期','to',ctx.params.get('to')||'',{type:'date'})}<input type="hidden" name="tab" value="${esc(ctx.params.get('tab')||'')}"><button class="shop-btn primary" type="submit">查询</button>${nav('重置','orders')}</form>`;}
function shopCalendarDay(ctx,value) {return String(ctx.date(value)).slice(0,10);}
function ordersPage(ctx) {const all=ownedOrders(ctx),tab=ctx.params.get('tab')||'',q=ctx.params.get('q')?.toLowerCase()||'',accountId=ctx.params.get('accountId')||'',from=ctx.params.get('from')||'',to=ctx.params.get('to')||'';const matches=all.filter(o=>(!tab||o.status===tab)&&(!accountId||o.accountId===accountId)&&(!q||`${o.no} ${list(o.items).map(i=>`${i.name} ${i.sku}`).join(' ')}`.toLowerCase().includes(q))&&(!from||shopCalendarDay(ctx,o.createdAt)>=from)&&(!to||shopCalendarDay(ctx,o.createdAt)<=to));const size=ctx.port==='mini'?5:8,pages=Math.max(1,Math.ceil(matches.length/size)),current=Math.max(1,Math.min(pages,Number(ctx.params.get('page'))||1)),params=Object.fromEntries(ctx.params);return page(ctx,TITLES.orders,`<nav class="shop-tabs" aria-label="订单状态">${[['','全部订单'],['pendingReview','待审核'],['awaitingPayment','待支付'],['paid','待发货'],['shipped','待收货'],['completed','已完成'],['rejected','已驳回'],['returning','退货中'],['cancelled','已取消']].map(([value,label])=>nav(`${label} ${value?all.filter(o=>o.status===value).length:all.length}`,'orders',{...params,tab:value,page:1},value===tab?'active':'')).join('')}</nav>${orderFilters(ctx)}<p class="shop-muted">${ctx.user?.isMain?'本企业主账号及子账号订单':'仅展示本账号提交的订单'} · 共 ${matches.length} 笔</p><div class="shop-order-list">${matches.slice((current-1)*size,current*size).map(o=>`<article class="shop-order-card"><div class="shop-order-top"><div><strong>${esc(o.no)}</strong><small>${esc(ctx.date(o.createdAt))} · ${esc(list(ctx.state.users).find(u=>u.id===o.accountId)?.name||'企业采购账号')}</small></div>${badge(o.status)}</div>${list(o.items).map(i=>`<div class="shop-line-item">${image(i)}<div><strong>${esc(i.name)}</strong><small>${esc(i.sku)} · ${esc(i.spec)}</small><span>${ctx.money(i.unitPrice)} × ${i.qty}</span></div></div>`).join('')}<div class="shop-order-foot"><span>${o.size==='large'?'大件':'小件'}订单 · ${list(o.items).reduce((n,i)=>n+Number(i.qty),0)} 件</span><strong>合计 ${ctx.money(o.total)}</strong></div>${o.reason?`<p class="shop-notice danger">驳回原因：${esc(o.reason)}</p>`:''}${orderButtons(ctx,o)}</article>`).join('')}</div>${!matches.length?empty('当前条件下没有订单',nav('查看全部订单','orders')):''}<nav class="shop-pagination" aria-label="订单分页">${nav('上一页','orders',{...params,page:Math.max(1,current-1)})}<span>第 ${current} / ${pages} 页</span>${nav('下一页','orders',{...params,page:Math.min(pages,current+1)})}</nav>`,orderCommands(ctx,all),root=>bindEvent(root,'[data-order-filter]','submit',form=>{const data=values(form);if(data.from&&data.to&&data.from>data.to)throw Error('开始日期不能晚于结束日期');ctx.navigate('orders',data);}));}
function reviewVersions(ctx,order) {
  const recorded=list(order.versions).filter(version=>version.snapshot),history=list(order.history);
  const submission=[...history].reverse().find(entry=>['提交订单','修改后重提'].includes(entry.action));
  const review=[...history].reverse().find(entry=>['审核通过','审核驳回'].includes(entry.action));
  const current={version:order.reviewVersion||1,submittedAt:submission?.time||order.createdAt,submittedBy:{name:submission?.userName||list(ctx.state.users).find(user=>user.id===order.accountId)?.name||''},status:order.status,reason:order.reason||'',reviewedAt:review?.time||'',reviewedBy:review?{name:review.userName}:null,snapshot:order};
  const versions=(recorded.length?recorded:[current]).slice().sort((a,b)=>Number(b.version)-Number(a.version));
  return '<section class="shop-section"><h2>'+(recorded.length?'历史审核版本':'当前审核版本')+'</h2><p class="shop-muted">'+(recorded.length?'每次审核使用当次提交的商品、价格与收货资料，后续修改不覆盖旧版本。展开版本查看详细内容。':'此订单尚未记录逐版历史快照，以下仅展示当前版本；历史审核原因可在订单进度记录中查看。')+'</p>'+versions.map(version=>{
    const snapshot=version.snapshot,address=snapshot.addressSnapshot||{},dealer=snapshot.dealerSnapshot||{},threshold=snapshot.thresholdSnapshot||{},commission=snapshot.commissionSnapshot||{};
    return '<details data-review-version="'+esc(version.version)+'"><summary>第 '+esc(version.version)+' 次审核 · '+esc(STATUS[version.status]||version.status)+' · '+ctx.money(snapshot.total)+'</summary>'+
      '<dl class="shop-definition"><dt>提交时间</dt><dd>'+esc(ctx.date(version.submittedAt))+'</dd><dt>提交账号</dt><dd>'+esc(version.submittedBy?.name||'—')+'</dd><dt>审核时间</dt><dd>'+esc(ctx.date(version.reviewedAt))+'</dd><dt>审核人员</dt><dd>'+esc(version.reviewedBy?.name||(version.status==='pendingReview'?'待审核':'未记录'))+'</dd><dt>审核结果</dt><dd>'+badge(version.status)+'</dd><dt>审核原因</dt><dd>'+esc(version.reason||snapshot.reason||'—')+'</dd><dt>收货联系人</dt><dd>'+esc(address.contact)+' '+esc(address.phone)+'</dd><dt>收货地址</dt><dd>'+esc(addressText(address))+'</dd><dt>企业名称</dt><dd>'+esc(dealer.name)+'</dd><dt>企业税号</dt><dd>'+esc(dealer.taxId)+'</dd><dt>订单备注</dt><dd>'+esc(text(snapshot.remark))+'</dd><dt>订单金额</dt><dd>'+ctx.money(snapshot.total)+'</dd><dt>总体积</dt><dd>'+Number(snapshot.volume||0).toFixed(3)+' m³</dd><dt>订单分类</dt><dd>'+(snapshot.size==='large'?'大件':'小件')+'</dd><dt>金额判定阈值</dt><dd>'+ctx.money(threshold.amountThreshold||0)+'</dd><dt>体积判定阈值</dt><dd>'+esc(threshold.volumeThreshold||0)+' m³</dd><dt>分佣比例快照</dt><dd>'+ (Number(commission.rate||0)*100).toFixed(2)+'%</dd></dl>'+
      '<div class="shop-table-wrap"><table class="shop-table"><thead><tr><th>商品 / SKU / 规格</th><th>数量</th><th>成交单价</th><th>金额小计</th><th>成交价来源</th></tr></thead><tbody>'+list(snapshot.items).map(item=>'<tr><td>'+esc(item.name)+'<br>'+esc(item.sku)+'<br>'+esc(item.spec)+'</td><td>'+esc(item.qty)+'</td><td>'+ctx.money(item.unitPrice)+'</td><td>'+ctx.money(item.lineTotal)+'</td><td>'+esc(priceSource(item.priceSource))+'</td></tr>').join('')+'</tbody></table></div></details>';
  }).join('')+'</section>';
}
function orderPage(ctx) {const o=ownedOrder(ctx,ctx.params.get('id'));if(!o)return page(ctx,TITLES.order,empty('订单不存在或不在当前账号权限范围',nav('返回我的订单','orders')));const payment=list(ctx.state.payments).find(p=>p.orderId===o.id),shipments=list(ctx.state.shipments).filter(s=>s.orderId===o.id),invoice=list(ctx.state.invoices).find(i=>i.orderId===o.id);return page(ctx,TITLES.order,`<section class="shop-section"><div class="shop-section-head"><h2>${esc(o.no)}</h2>${badge(o.status)}</div><p class="shop-muted">下单时间 ${esc(ctx.date(o.createdAt))} · ${o.size==='large'?'大件':'小件'}订单 · 第 ${o.reviewVersion||1} 次审核</p>${o.reason?`<p class="shop-notice danger">驳回原因：${esc(o.reason)}</p>`:''}${orderButtons(ctx,o,false)}</section><section class="shop-section"><h2>收货信息</h2><p><strong>${esc(o.addressSnapshot?.contact)}</strong> ${esc(o.addressSnapshot?.phone)}</p><p>${esc(addressText(o.addressSnapshot))}</p><details><summary>下单企业与订单分类快照</summary><dl class="shop-definition"><dt>企业名称</dt><dd>${esc(o.dealerSnapshot?.name)}</dd><dt>企业税号</dt><dd>${esc(o.dealerSnapshot?.taxId)}</dd><dt>订单体积</dt><dd>${Number(o.volume||0).toFixed(3)} m³</dd><dt>金额阈值</dt><dd>${ctx.money(o.thresholdSnapshot?.amountThreshold||0)}</dd><dt>体积阈值</dt><dd>${esc(o.thresholdSnapshot?.volumeThreshold||0)} m³</dd></dl></details></section><section class="shop-section"><h2>成交商品明细</h2>${list(o.items).map(i=>`<div class="shop-line-item">${image(i)}<div><strong>${esc(i.name)}</strong><small>${esc(i.sku)} · ${esc(i.spec)}</small><p>${ctx.money(i.unitPrice)} × ${i.qty} = ${ctx.money(i.lineTotal)}</p><small>成交价格来源：${esc(priceSource(i.priceSource))}</small></div></div>`).join('')}<div class="shop-order-foot"><span>订单备注：${esc(text(o.remark))}</span><strong class="shop-total">${ctx.money(o.total)}</strong></div></section><section class="shop-section"><h2>支付与物流</h2>${payment?`<dl class="shop-definition"><dt>支付渠道</dt><dd>${esc({wechat:'微信支付',alipay:'支付宝',unionpay:'银联支付'}[payment.channel])}</dd><dt>支付金额</dt><dd>${ctx.money(payment.amount)}</dd><dt>支付流水</dt><dd>${esc(payment.transactionNo)}</dd><dt>支付时间</dt><dd>${esc(ctx.date(payment.time))}</dd></dl>`:'<p class="shop-muted">尚未完成付款</p>'}${o.tracking?`<p>承运公司：${esc(o.carrier)} · 运单号：${esc(o.tracking)}</p>`:''}${shipments.length?shipments.map(s=>`<p>${esc(ctx.date(s.time))}　${esc(s.carrier)}　${esc(s.tracking)}　发货 ${esc(s.qty)} 件</p>`).join(''):'<p class="shop-muted">尚未发货，请在付款后等待发货通知。</p>'}${invoice?nav('查看发票进度','invoices',{id:invoice.id}):''}</section>${reviewVersions(ctx,o)}<section class="shop-section"><h2>订单进度记录</h2>${list(o.history).length?`<ol class="shop-timeline">${o.history.map(h=>`<li><strong>${esc(STATUS[h.status]||h.action||h.type||'订单更新')}</strong><span>${esc(ctx.date(h.time||h.at))}</span><p>${esc(h.reason||h.detail||h.note||'')}</p></li>`).join('')}</ol>`:'<p class="shop-muted">当前订单暂无历史变更</p>'}${nav('返回我的订单','orders')}</section>`,orderCommands(ctx,[o]));}
function payPage(ctx) {const o=ownedOrder(ctx,ctx.params.get('id'));if(!o)return page(ctx,TITLES.pay,empty('订单不存在或无访问权限',nav('返回我的订单','orders')));if(o.status!=='awaitingPayment')return page(ctx,'支付结果',`<section class="shop-section"><h2>${['paid','shipped','completed','returning','refunded'].includes(o.status)?'此订单已完成付款':'当前订单不可付款'}</h2>${badge(o.status)}<p>${esc(o.no)} · ${ctx.money(o.total)}</p>${nav('查看订单','order',{id:o.id},'primary')}</section>`);const channels=ctx.port==='mini'?[['wechat','微信支付']]:[['wechat','微信支付'],['alipay','支付宝'],['unionpay','银联支付']];const notifyKey=token();return page(ctx,TITLES.pay,`<section class="shop-section shop-payment"><h2>订单已审核通过，请完成付款</h2><p>订单编号 ${esc(o.no)}</p><p>审核后应付金额</p><strong class="shop-payment-amount">${ctx.money(o.total)}</strong><fieldset><legend>选择支付方式</legend><div class="shop-payment-channels">${channels.map(([value,label],i)=>`<label><input type="radio" name="channel" value="${value}" ${i===0?'checked':''}>${label}</label>`).join('')}</div></fieldset><div class="shop-notice">支付成功后订单进入待发货状态。</div><div class="shop-actions">${button('确认支付','pay-success','','primary')}${button('取消本次支付','pay-failure')}${nav('稍后支付','order',{id:o.id})}</div><div data-payment-result aria-live="polite"></div></section>`,{
    'pay-success':async(_,root)=>{const channel=root.querySelector('[name="channel"]:checked')?.value;if(!channel)throw Error('请选择支付渠道');await ctx.run('payOrder',{id:o.id,channel,success:true,notifyKey});ctx.navigate('order',{id:o.id});},
    'pay-failure':async(_,root)=>{const channel=root.querySelector('[name="channel"]:checked')?.value;try{await ctx.run('payOrder',{id:o.id,channel,success:false,notifyKey:token()});}finally{root.querySelector('[data-payment-result]').innerHTML='<p class="shop-error" role="alert">支付未完成，订单仍待支付。请重新选择渠道后重试。</p>';}}
  });}
function refundAttempts(state,returnId) {
  return list(state.refunds).filter(refund=>refund.returnId===returnId)
    .map((refund,index)=>({refund,index,time:Date.parse(refund.time)}))
    .sort((a,b)=>{const at=Number.isFinite(a.time)?a.time:-Infinity,bt=Number.isFinite(b.time)?b.time:-Infinity;return at===bt?b.index-a.index:bt-at;})
    .map(({refund})=>refund);
}
function refundHistory(ctx,attempts) {
  if(!attempts.length)return '';
  return '<details><summary>退款处理记录（'+attempts.length+'次）</summary><div class="shop-table-wrap"><table class="shop-table"><thead><tr><th>尝试</th><th>处理时间</th><th>原路渠道</th><th>退款金额</th><th>处理结果</th></tr></thead><tbody>'+attempts.map((refund,index)=>'<tr data-refund-attempt="'+esc(refund.id)+'"><td>'+ (attempts.length-index)+'</td><td>'+esc(ctx.date(refund.time))+'</td><td>'+esc({wechat:'微信支付',alipay:'支付宝',unionpay:'银联支付'}[refund.channel]||refund.channel)+'</td><td>'+ctx.money(refund.amount)+'</td><td>'+badge(refund.status)+'</td></tr>').join('')+'</tbody></table></div></details>';
}
function aftersalesPage(ctx) {const orders=ownedOrders(ctx),ids=new Set(orders.map(o=>o.id)),returns=list(ctx.state.returns).filter(r=>ids.has(r.orderId));const id=ctx.params.get('id'),orderId=ctx.params.get('orderId'),status=ctx.params.get('tab')||'',q=ctx.params.get('q')||'';const records=returns.filter(r=>(!id||r.id===id)&&(!orderId||r.orderId===orderId)&&(!status||r.status===status)&&(!q||`${orders.find(o=>o.id===r.orderId)?.no} ${r.reason}`.includes(q)));return page(ctx,TITLES.aftersales,`<form data-after-filter class="shop-filters">${field('订单或原因','q',q,{placeholder:'订单编号 / 拒收原因'})}${field('处理进度','tab',status,{type:'select',options:[{value:'',label:'全部进度'},...['requested','received','refundFailed','refunded'].map(s=>({value:s,label:STATUS[s]}))]})}<button class="shop-btn primary" type="submit">查询</button>${nav('重置','aftersales')}</form><div class="shop-order-list">${records.map(r=>{const o=orders.find(o=>o.id===r.orderId),attempts=refundAttempts(ctx.state,r.id),refund=attempts.find(f=>f.status==='success')||attempts[0],payment=list(ctx.state.payments).find(p=>p.orderId===r.orderId);return `<article class="shop-order-card"><div class="shop-section-head"><h2>${esc(o.no)}</h2>${badge(r.status)}</div><p class="shop-muted">拒收申请时间 ${esc(ctx.date(r.time))}</p><dl class="shop-definition"><dt>拒收原因</dt><dd>${esc(r.reason)}</dd><dt>整单退货金额</dt><dd>${ctx.money(o.total)}</dd><dt>原支付渠道</dt><dd>${esc({wechat:'微信支付',alipay:'支付宝',unionpay:'银联支付'}[payment?.channel]||'—')}</dd><dt>退回收货进度</dt><dd>${r.status==='requested'?'等待退回商品收货确认':'退回商品已确认收货'}</dd><dt>退款结果</dt><dd>${refund?`${STATUS[refund.status]||refund.status} · ${ctx.money(refund.amount)}`:r.status==='refundFailed'?'退款失败，业务人员处理中':'等待退回收货后原路退款'}</dd></dl>${refundHistory(ctx,attempts)}${nav('查看原订单','order',{id:o.id})}${!id?nav('售后详情','aftersales',{id:r.id}):nav('返回售后列表','aftersales')}</article>`;}).join('')}</div>${!records.length?empty('当前条件下暂无售后申请',nav('查看我的订单','orders')):''}`,{},root=>bindEvent(root,'[data-after-filter]','submit',form=>ctx.navigate('aftersales',values(form))));}

function profilePage(ctx) {const dealer=ownDealer(ctx);if(!dealer)return page(ctx,TITLES.profile,empty('未找到企业档案'));const pending=dealer.pendingProfile?.data||dealer.pendingProfile,main=ctx.user?.isMain;const source=dealer.pendingProfile?.status==='rejected'?pending:dealer;return page(ctx,TITLES.profile,`<section class="shop-section"><div class="shop-section-head"><h2>当前已审核企业资料</h2>${badge(dealer.status)}</div><dl class="shop-definition">${PROFILE.map(([label,key])=>`<dt>${label}</dt><dd>${esc(dealer[key])}</dd>`).join('')}<dt>关联档案编码</dt><dd>${esc(dealer.smartCode||'未关联')}</dd><dt>经销商等级</dt><dd>${esc(list(ctx.state.grades).find(g=>g.id===dealer.gradeId)?.name)}</dd><dt>授权经营区域</dt><dd>${esc(list(dealer.regions).join('、'))}</dd></dl>${dealer.license?`<details><summary>查看营业执照</summary><img class="shop-license" src="${esc(dealer.license)}" alt="已审核营业执照"></details>`:''}</section>${pending?`<section class="shop-section shop-pending"><h2>本次提交的修改资料</h2><p class="shop-notice">${dealer.pendingProfile.status==='rejected'?'资料修改已驳回，请修正后重提':'新资料待复审；审核通过前，当前已审核资料继续生效。'}</p>${dealer.pendingProfile.reason?`<p class="shop-error">${esc(dealer.pendingProfile.reason)}</p>`:''}<dl class="shop-definition">${PROFILE.map(([label,key])=>`<dt>${label}</dt><dd>${esc(pending[key])}</dd>`).join('')}</dl>${pending.license?`<img class="shop-license" src="${esc(pending.license)}" alt="待复审营业执照">`:''}</section>`:''}${main?`<form data-profile-form class="shop-section"><h2>修改企业资料</h2><p class="shop-muted">核心信息变更将提交复审，不会直接覆盖已审核版本。</p><div class="shop-form-grid">${fields(PROFILE,source||{})}</div><label class="shop-field"><span>更换营业执照</span><input name="licenseFile" type="file" accept="image/png,image/jpeg,image/webp"><small>不选择文件则保留当前营业执照。</small></label><div data-license-preview></div><button type="submit" class="shop-btn primary">提交资料复审</button></form>`:'<div class="shop-notice">企业资料由主账号维护，当前采购账号只能查看。</div>'}<section class="shop-section"><h2>资料审核记录</h2>${list(dealer.history).length?`<ol class="shop-timeline">${dealer.history.map(h=>`<li><strong>${esc(STATUS[h.status]||h.action||h.type||'资料更新')}</strong><span>${esc(ctx.date(h.time||h.at))}</span><p>${esc(h.reason||h.detail||'')}</p>${h.before?`<details><summary>查看变更前资料</summary><dl class="shop-definition">${PROFILE.map(([label,key])=>`<dt>${label}</dt><dd>${esc(h.before[key])}</dd>`).join('')}</dl></details>`:''}</li>`).join('')}</ol>`:'<p class="shop-muted">暂无资料变更记录</p>'}</section>`,{},root=>{if(!main)return;let license=source?.license||dealer.license,upload=null;bindEvent(root,'[name="licenseFile"]','change',async input=>{const file=input.files?.[0];if(!file)return;upload=ctx.readImage(file);try{const result=await upload;license=typeof result==='string'?result:result?.url||result?.dataUrl;if(!license)throw Error('执照读取失败，请重新选择');root.querySelector('[data-license-preview]').innerHTML=`<img class="shop-license" src="${esc(license)}" alt="新营业执照预览">`;}finally{upload=null;}});bindEvent(root,'[data-profile-form]','submit',async form=>{if(upload)await upload;const data=values(form);if(!license)throw Error('请上传营业执照');await ctx.run('changeProfile',{...Object.fromEntries(PROFILE.map(([,key])=>[key,data[key]])),license});ctx.refresh();});});}
function accountDialog(ctx,account={}) {return scopedModal(ctx,account.id?'编辑企业子账号':'新增企业子账号',`${field('账号姓名','name',account.name||'',{required:true})}${field('登录手机号','phone',account.phone||'',{type:'tel',required:true})}${field(account.id?'新密码（留空保留）':'初始密码','password','',{type:'password',required:!account.id,help:'至少6位字符；密码由采购人员登录后自行修改'})}${check('启用账号','enabled',account.enabled!==false)}`,async(data,form)=>{await ctx.run('saveSubAccount',{...(account.id?{id:account.id}:{}),name:data.name,phone:data.phone,...(data.password?{password:data.password}:{}),enabled:form.querySelector('[name="enabled"]').checked});ctx.refresh();},{saveLabel:'保存子账号'});}
function accountsPage(ctx) {if(!ctx.user?.isMain)return page(ctx,TITLES.accounts,empty('仅企业主账号可管理子账号',nav('返回个人中心','me')));const accounts=list(ctx.state.users).filter(u=>u.kind==='dealer'&&u.dealerId===ctx.user.dealerId&&!u.isMain),q=ctx.params.get('q')||'',status=ctx.params.get('tab')||'',matches=accounts.filter(u=>(!q||`${u.name} ${u.phone}`.includes(q))&&(!status||(status==='enabled')===u.enabled));return page(ctx,TITLES.accounts,`<div class="shop-section-head"><p>${esc(ownDealer(ctx)?.name)}</p>${button('新增子账号','account-add','','primary')}</div><form data-account-filter class="shop-filters">${field('账号检索','q',q,{placeholder:'姓名 / 手机号'})}${field('账号状态','tab',status,{type:'select',options:[{value:'',label:'全部账号'},{value:'enabled',label:'已启用'},{value:'disabled',label:'已停用'}]})}<button type="submit" class="shop-btn primary">查询</button>${nav('重置','accounts')}</form><div class="shop-table-wrap"><table class="shop-table"><thead><tr><th>姓名</th><th>登录手机号</th><th>所属企业</th><th>状态</th><th>操作</th></tr></thead><tbody>${matches.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.phone)}</td><td>${esc(ownDealer(ctx)?.name)}</td><td>${badge(u.enabled?'approved':'cancelled')}</td><td><div class="shop-actions">${button('编辑','account-edit',`data-account-id="${esc(u.id)}"`,'link')}${button(u.enabled?'停用':'启用','account-toggle',`data-account-id="${esc(u.id)}"`,'link')}${nav('查看订单','orders',{accountId:u.id})}</div></td></tr>`).join('')}</tbody></table></div>${!matches.length?empty('没有符合条件的子账号'):''}`,{'account-add':()=>accountDialog(ctx),'account-edit':el=>accountDialog(ctx,accounts.find(u=>u.id===el.dataset.accountId)),'account-toggle':async el=>{const u=accounts.find(u=>u.id===el.dataset.accountId);if(!u)throw Error('子账号已不存在');if(await ctx.confirm(u.enabled?'停用子账号':'启用子账号',u.enabled?`停用 ${esc(u.name)} 后，该账号无法登录或继续订货。`:`确定启用 ${esc(u.name)}？`)){await ctx.run('saveSubAccount',{id:u.id,name:u.name,phone:u.phone,enabled:!u.enabled});ctx.refresh();}}},root=>bindEvent(root,'[data-account-filter]','submit',form=>ctx.navigate('accounts',values(form))));}

function invoiceLines(ctx,i,o) {const p=i.profileSnapshot||{};return [`发票号码：${i.invoiceNo||'—'}`,`开票状态：${STATUS[i.status]||i.status}`,`原订单：${o?.no||'—'}`,`开票时间：${ctx.date(i.time)}`,...INVOICE.map(([label,key])=>`${label}：${p[key]||'—'}`),'商品明细',...list(o?.items).map(item=>`${item.sku} ${item.name} ${item.spec} × ${item.qty}  ${ctx.money(item.lineTotal)}`),`价税合计：${ctx.money(o?.total||0)}`];}
function invoicePdf(ctx,i,o,preview=false) {return ctx.downloadPdf(`电子发票_${i.invoiceNo||o?.no||'订单'}.pdf`,invoiceLines(ctx,i,o)).then(url=>{if(preview){if(typeof url!=='string'||!url.startsWith('blob:'))throw Error('PDF预览文件未生成，请重试');return ctx.modal('电子发票PDF',`<div class="shop shop-${esc(ctx.port)}"><iframe class="shop-pdf-frame" src="${esc(url)}" title="电子发票PDF"></iframe><p>已生成真实PDF文件，可在浏览器下载中保存。</p></div>`,()=>{}, {saveLabel:'关闭',wide:ctx.port==='pc'});}return url;});}
function invoicesPage(ctx) {
  const p=invoiceProfile(ctx),allOrders=ownedOrders(ctx),ids=new Set(allOrders.map(o=>o.id)),all=list(ctx.state.invoices).filter(i=>i.dealerId===ctx.user?.dealerId&&ids.has(i.orderId)),q=ctx.params.get('q')||'',tab=ctx.params.get('tab')||'',id=ctx.params.get('id');const records=all.filter(i=>(!id||i.id===id)&&(!tab||tab==='profile'||i.status===tab)&&(!q||`${i.invoiceNo||''} ${allOrders.find(o=>o.id===i.orderId)?.no||''}`.includes(q)));const eligible=allOrders.filter(o=>o.status==='completed'&&!all.some(i=>i.orderId===o.id));
  return page(ctx,TITLES.invoices,`<section class="shop-section"><h2>企业开票资料</h2><p class="shop-muted">首次开票可在此创建资料；后续修改不影响历史发票的抬头快照。</p><form data-invoice-profile><div class="shop-form-grid">${invoiceForm(p||{title:ownDealer(ctx)?.name,taxId:ownDealer(ctx)?.taxId})}</div><button type="submit" class="shop-btn primary">保存开票资料</button></form></section><section class="shop-section"><h2>申请订单发票</h2><form data-invoice-request><div class="shop-filters">${field('已收货待开票订单','orderId',ctx.params.get('orderId')||'',{type:'select',required:true,options:[{value:'',label:eligible.length?'请选择已完成订单':'暂无可开票订单'},...eligible.map(o=>({value:o.id,label:`${o.no} · ${ctx.money(o.total)}`}))]})}<button type="submit" class="shop-btn primary" ${!eligible.length?'disabled':''}>申请发票</button></div><p class="shop-muted">申请时使用上方填写的开票资料，可直接补充后提交。</p></form></section><section class="shop-section"><h2>我的发票</h2><form data-invoice-filter class="shop-filters">${field('发票检索','q',q,{placeholder:'发票号 / 订单号'})}${field('开票进度','tab',tab,{type:'select',options:[{value:'',label:'全部发票'},...['pending','issued','failed'].map(s=>({value:s,label:STATUS[s]}))]})}<button type="submit" class="shop-btn primary">查询</button>${nav('重置','invoices')}</form><div class="shop-order-list">${records.map(i=>{const o=allOrders.find(o=>o.id===i.orderId),snapshot=i.profileSnapshot||{};return `<article class="shop-invoice-card"><div class="shop-section-head"><h3>${esc(o.no)}</h3>${badge(i.status)}</div><dl class="shop-definition"><dt>发票抬头</dt><dd>${esc(snapshot.title)}</dd><dt>纳税人识别号</dt><dd>${esc(snapshot.taxId)}</dd><dt>开票金额</dt><dd>${ctx.money(o.total)}</dd><dt>发票号码</dt><dd>${esc(i.invoiceNo||'待开具')}</dd><dt>申请时间</dt><dd>${esc(ctx.date(i.time))}</dd><dt>接收邮箱</dt><dd>${esc(snapshot.email)}</dd></dl>${i.status==='failed'?'<p class="shop-notice danger">开票处理失败，业务人员正在处理，原申请记录保留。</p>':''}<details><summary>查看开票资料快照</summary><dl class="shop-definition">${INVOICE.map(([label,key])=>`<dt>${label}</dt><dd>${esc(snapshot[key])}</dd>`).join('')}</dl></details><div class="shop-actions">${nav('原订单','order',{id:o.id})}${i.status==='issued'?`${button('查看PDF','invoice-view',`data-invoice-id="${esc(i.id)}"`)}${button('下载PDF','invoice-download',`data-invoice-id="${esc(i.id)}"`,'primary')}`:''}</div></article>`;}).join('')}</div>${!records.length?empty('当前条件下暂无发票记录'):''}</section>`,{
    'invoice-view':el=>{const i=all.find(i=>i.id===el.dataset.invoiceId);if(!i||i.status!=='issued')throw Error('发票尚未开具');return invoicePdf(ctx,i,allOrders.find(o=>o.id===i.orderId),true);},
    'invoice-download':el=>{const i=all.find(i=>i.id===el.dataset.invoiceId);if(!i||i.status!=='issued')throw Error('发票尚未开具');return invoicePdf(ctx,i,allOrders.find(o=>o.id===i.orderId));}
  },root=>{bindEvent(root,'[data-invoice-profile]','submit',async form=>{await ctx.run('saveInvoiceProfile',Object.fromEntries(INVOICE.map(([,key])=>[key,values(form)[key]])));ctx.refresh();});bindEvent(root,'[data-invoice-request]','submit',async form=>{const data=values(form),o=eligible.find(o=>o.id===data.orderId);if(!o)throw Error('请选择已收货且未申请过发票的订单');const profileForm=root.querySelector('[data-invoice-profile]');if(!profileForm.reportValidity())return;const profile=values(profileForm);await ctx.run('requestInvoice',{id:o.id,profile:Object.fromEntries(INVOICE.map(([,key])=>[key,profile[key]]))});ctx.refresh();});bindEvent(root,'[data-invoice-filter]','submit',form=>ctx.navigate('invoices',values(form)));});
}
function commissionAllowed(ctx) {const d=ownDealer(ctx);return Boolean(ctx.user?.isMain&&list(ctx.state.grades).find(g=>g.id===d?.gradeId)?.level===1);}
function commissionsPage(ctx) {if(!commissionAllowed(ctx))return page(ctx,TITLES.commissions,empty('仅一级经销商企业主账号可查看本人佣金',nav('返回个人中心','me')));const all=list(ctx.query('commissions')),tab=ctx.params.get('tab')||'',q=ctx.params.get('q')||'',from=ctx.params.get('from')||'',to=ctx.params.get('to')||'';const records=all.filter(c=>(!tab||c.status===tab)&&(!q||`${c.orderNo||''} ${c.childDealerName||''}`.includes(q))&&(!from||shopCalendarDay(ctx,c.time)>=from)&&(!to||shopCalendarDay(ctx,c.time)<=to));const sum=status=>all.filter(c=>c.status===status).reduce((n,c)=>n+Number(c.amount),0);return page(ctx,TITLES.commissions,`<div class="shop-finance-totals"><div><span>待结算佣金</span><strong>${ctx.money(sum('unsettled'))}</strong></div><div><span>已结算佣金</span><strong>${ctx.money(sum('settled'))}</strong></div></div><form data-commission-filter class="shop-filters">${field('订单或下级企业','q',q,{placeholder:'订单编号 / 下级企业名称'})}${field('结算状态','tab',tab,{type:'select',options:[{value:'',label:'全部状态'},{value:'unsettled',label:'待结算'},{value:'settled',label:'已结算'}]})}${field('开始日期','from',from,{type:'date'})}${field('结束日期','to',to,{type:'date'})}<button type="submit" class="shop-btn primary">查询</button>${nav('重置','commissions')}${button('导出佣金记录','commission-export')}</form><div class="shop-table-wrap"><table class="shop-table"><thead><tr><th>完成订单</th><th>二级企业</th><th>计佣基数</th><th>比例快照</th><th>佣金金额</th><th>完成日期</th><th>结算状态</th><th>操作</th></tr></thead><tbody>${records.map(c=>`<tr><td>${esc(c.orderNo||'完成订单')}</td><td>${esc(c.childDealerName||'下级经销企业')}</td><td>${ctx.money(c.base)}</td><td>${(Number(c.rate)*100).toFixed(2)}%</td><td>${ctx.money(c.amount)}</td><td>${esc(ctx.date(c.time))}</td><td>${badge(c.status)}</td><td>${button('查看记录','commission-detail',`data-commission-id="${esc(c.id)}"`,'link')}</td></tr>`).join('')}</tbody></table></div>${!records.length?empty('该期间暂无佣金记录，二级订单完成收货后计佣'):''}`,{
    'commission-export':()=>ctx.downloadExcel('我的佣金记录.xlsx',records.map(c=>({订单编号:c.orderNo||'',二级企业:c.childDealerName||'',计佣基数:c.base,计佣比例:c.rate,佣金金额:c.amount,结算状态:STATUS[c.status],完成日期:ctx.date(c.time)}))),
    'commission-detail':el=>{const c=all.find(c=>c.id===el.dataset.commissionId);if(!c)throw Error('记录不存在');return scopedModal(ctx,'佣金记录详情',`<dl class="shop-definition shop-full"><dt>完成订单</dt><dd>${esc(c.orderNo||'完成订单')}</dd><dt>二级企业</dt><dd>${esc(c.childDealerName||'下级经销企业')}</dd><dt>计佣基数</dt><dd>${ctx.money(c.base)}</dd><dt>比例快照</dt><dd>${(Number(c.rate)*100).toFixed(2)}%</dd><dt>佣金金额</dt><dd>${ctx.money(c.amount)}</dd><dt>状态</dt><dd>${STATUS[c.status]}</dd><dt>结算批次</dt><dd>${esc(c.batchId||'待结算')}</dd><dt>完成时间</dt><dd>${esc(ctx.date(c.time))}</dd></dl>`,()=>{}, {saveLabel:'关闭'});}
  },root=>bindEvent(root,'[data-commission-filter]','submit',form=>{const data=values(form);if(data.from&&data.to&&data.from>data.to)throw Error('开始日期不能晚于结束日期');ctx.navigate('commissions',data);}));}
function reconciliationPage(ctx) {const dealer=ownDealer(ctx),from=ctx.params.get('from')||'',to=ctx.params.get('to')||'';let statement;try{statement=ctx.query('reconciliation',{dealerId:dealer?.id,from,to})||{};}catch(error){return page(ctx,TITLES.reconciliation,`<p class="shop-error">${esc(error.message)}</p>${nav('重置期间','reconciliation')}`);}const orders=list(statement.orders),payments=list(statement.payments),refunds=list(statement.refunds),settled=list(statement.commissionSettled||statement.settlements);const own=ownedOrders(ctx);const findOrder=id=>own.find(o=>o.id===id),money=n=>ctx.money(n||0);const rows=rows=>rows.map(row=>`<tr><td>${esc(row.time||row.createdAt?ctx.date(row.time||row.createdAt):'—')}</td><td>${esc(row.no||findOrder(row.orderId)?.no||row.transactionNo||row.batchId||'结算记录')}</td><td>${esc(row.channel?({wechat:'微信',alipay:'支付宝',unionpay:'银联'}[row.channel]||row.channel):STATUS[row.status]||'')}</td><td>${money(row.amount??row.total)}</td><td>${row.orderId&&findOrder(row.orderId)?nav('原订单','order',{id:row.orderId},'link'):row.id&&own.some(o=>o.id===row.id)?nav('订单详情','order',{id:row.id},'link'):''}</td></tr>`).join('');const table=(title,data)=>`<section class="shop-section"><h2>${title}</h2>${data.length?`<div class="shop-table-wrap"><table class="shop-table"><thead><tr><th>日期</th><th>关联单据</th><th>状态 / 渠道</th><th>金额</th><th>追溯</th></tr></thead><tbody>${rows(data)}</tbody></table></div>`:empty(`本期间暂无${title}`)}</section>`;const amount=statement.commissionSettledAmount??(typeof statement.commissionSettled==='number'?statement.commissionSettled:settled.reduce((n,s)=>n+Number(s.total||s.amount||0),0));return page(ctx,TITLES.reconciliation,`<form data-statement-filter class="shop-filters">${field('企业','dealerName',dealer?.name||'',{readonly:true})}${field('开始日期','from',from,{type:'date'})}${field('结束日期','to',to,{type:'date'})}<button type="submit" class="shop-btn primary">查看对账单</button>${nav('全部期间','reconciliation')}${button('下载对账单PDF','statement-download')}</form><div class="shop-finance-totals">${[['订单应收',statement.receivable],['累计支付',statement.totalPaid],['累计退款',statement.totalRefunded],['待付余额',statement.balance],['已结算佣金',amount]].map(([label,n])=>`<div><span>${label}</span><strong>${money(n)}</strong></div>`).join('')}</div><p class="shop-muted">仅查看本企业 ${from||'全部开始日期'} 至 ${to||'全部结束日期'} 的资金记录。逐笔明细可回查原订单。</p>${table('订单应收明细',orders)}${table('支付明细',payments)}${table('退款明细',refunds)}${commissionAllowed(ctx)?table('佣金结算明细',settled):''}`,{
    'statement-download':()=>ctx.downloadPdf('企业对账单.pdf',[`企业：${dealer?.name}`,`期间：${from||'全部'} 至 ${to||'全部'}`,`订单应收：${money(statement.receivable)}`,`累计支付：${money(statement.totalPaid)}`,`累计退款：${money(statement.totalRefunded)}`,`待付余额：${money(statement.balance)}`,`已结算佣金：${money(amount)}`,...orders.map(o=>`订单 ${o.no}  ${money(o.total)}`),...payments.map(p=>`支付 ${findOrder(p.orderId)?.no||p.transactionNo}  ${money(p.amount)}`),...refunds.map(r=>`退款 ${findOrder(r.orderId)?.no||''}  ${money(r.amount)}`)])
  },root=>bindEvent(root,'[data-statement-filter]','submit',form=>{const data=values(form);if(data.from&&data.to&&data.from>data.to)throw Error('开始日期不能晚于结束日期');ctx.navigate('reconciliation',{from:data.from,to:data.to});}));}
function passwordPage(ctx) {return page(ctx,TITLES.password,`<section class="shop-section shop-password"><p>当前账号 ${esc(ctx.user?.phone)} · ${esc(ctx.user?.name)}</p><form data-password-form>${field('原密码','oldPassword','',{type:'password',required:true,autocomplete:'current-password'})}${field('新密码','newPassword','',{type:'password',required:true,autocomplete:'new-password',help:'至少6位字符'})}${field('确认新密码','confirmation','',{type:'password',required:true,autocomplete:'new-password'})}<button class="shop-btn primary" type="submit">保存并重新登录</button><p class="shop-muted">修改成功后旧密码失效，当前账号需要重新登录。</p></form></section>`,{},root=>bindEvent(root,'[data-password-form]','submit',async form=>{const data=values(form);if(data.newPassword!==data.confirmation)throw Error('两次输入的新密码不一致');await ctx.run('changePassword',{oldPassword:data.oldPassword,newPassword:data.newPassword,confirmation:data.confirmation});ctx.navigate('login');}));}
function mePage(ctx) {const dealer=ownDealer(ctx),grade=list(ctx.state.grades).find(g=>g.id===dealer?.gradeId),orders=ownedOrders(ctx);return page(ctx,TITLES.me,`<section class="shop-me-head"><img src="assets/logo.png" alt="苏泊尔"><div><h2>${esc(ctx.user?.name)}</h2><p>${esc(dealer?.name)}</p><span>${esc(ctx.user?.phone)} · ${ctx.user?.isMain?'企业主账号':'企业采购账号'} · ${esc(grade?.name)}</span></div></section><section class="shop-section"><div class="shop-section-head"><h2>我的订单</h2>${nav('全部订单','orders')}</div><div class="shop-shortcuts">${[['pendingReview','待审核'],['awaitingPayment','待支付'],['paid','待发货'],['shipped','待收货']].map(([status,label])=>nav(`${label} ${orders.filter(o=>o.status===status).length}`,'orders',{tab:status})).join('')}</div></section><section class="shop-section shop-account-menu"><h2>企业与账户服务</h2>${[['企业资料','profile'],...(ctx.user?.isMain?[['企业子账号','accounts']]:[]),['收货地址','addresses'],['售后服务','aftersales'],['开票信息与发票','invoices'],...(commissionAllowed(ctx)?[['我的佣金','commissions']]:[]),['我的对账单','reconciliation'],['修改密码','password']].map(([label,route])=>nav(label,route,{},'menu')).join('')}</section>`);}

export function renderShop(input) {
  if(!['pc','mini'].includes(input.port)||!Object.hasOwn(TITLES,input.route))return null;
  const ctx={...input,money:value=>`¥${input.money(value)}`,query:(type,payload)=>{const result=input.query(type,payload);return type==='commissions'?list(result).map(c=>({...c,orderNo:c.orderNo||c.orderId,childDealerName:c.childDealerName||list(input.state.dealers).find(d=>d.id===c.childDealerId)?.name||c.childDealerId})):result;}};
  const routes={login:loginPage,register:registrationPage,agreement:agreementPage,home:homePage,products:productsPage,product:productPage,bulk:bulkPage,cart:cartPage,checkout:checkoutPage,orders:ordersPage,order:orderPage,pay:payPage,aftersales:aftersalesPage,profile:profilePage,accounts:accountsPage,addresses:addressesPage,invoices:invoicesPage,commissions:commissionsPage,reconciliation:reconciliationPage,password:passwordPage,me:mePage};
  if(!ctx.user&&!['login','register','agreement'].includes(ctx.route))return loginPage(ctx);
  if(ctx.user?.kind==='dealer'&&ownDealer(ctx)?.status!=='approved'&&!['login','register','agreement'].includes(ctx.route))return registrationPage(ctx);
  return routes[ctx.route]?.(ctx)||null;
}
